// Nushell: backend (raw strings r#'...'# need no escaping) + emitter (nu 0.100+).
// Nushell `def` bodies can't see the script's variables, so functions may only use their
// parameters and locals; anything else is a clear emit error.
#include "shell.hpp"
#include "emit_dialect.hpp"
namespace {
using namespace forge::script;
std::string rq(const std::string& s) { std::string h = "#"; while (s.find("'" + h) != std::string::npos) h += '#'; return "r" + h + "'" + s + "'" + h; }
struct nu_dialect : block_dialect {
    std::string header() override { return "#!/usr/bin/env -S nu --no-config-file\n# generated by `forge script --emit nu`; runs without FORGE\n"; }
    void glob(bool g) { if (g && cx->in_fn) no("a Nushell function using a script-level variable (def bodies can't capture variables; pass it as a parameter)"); }
    std::string s_lit(const std::string& s) override { return rq(s); }
    std::string ref(const std::string& n, ety, bool g) override { glob(g); return "$" + n; }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        if (op == '/') return "((" + a + " / " + b + ") | into int)";
        if (op == '%') return "(" + a + " - " + b + " * ((" + a + " / " + b + ") | into int))";
        return "(" + a + " " + op + " " + b + ")";
    }
    std::string neg(const std::string& a) override { return "(0 - " + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o = "(["; for (std::size_t i = 0; i < p.size(); ++i) o += (i ? " " : "") + p[i]; return o + "] | str join)"; }
    std::string i2s(const std::string& i) override { return "(" + i + " | into string)"; }
    std::string s2i(const std::string& s) override { return "(" + s + " | into int)"; }
    std::string slen(const std::string& s) override { return "(" + s + " | str length)"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool) override { return "(" + a + " " + op + " " + b + ")"; }
    std::string c_and(const std::string& a, const std::string& b) override { return "(" + a + " and " + b + ")"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "(" + a + " or " + b + ")"; }
    std::string c_not(const std::string& a) override { return "(not " + a + ")"; }
    std::string c_bool(bool v) override { return v ? "true" : "false"; }
    std::string truthy(const std::string& v) override { return "(" + v + " == 'true')"; }
    void let(const std::string& n, const std::string& v, ety, bool g, bool decl) override { glob(g); L((decl ? "mut " + n : "$" + n) + " = " + v); }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("print ") + (err ? "-e " : "") + (nl ? "" : "-n ") + v); }
    void if_(const std::string& c) override { open("if " + c + " {"); }
    void else_() override { mid("} else {"); }
    void end_if() override { close("}"); }
    void while_(const std::string& c) override { open("while " + c + " {"); }
    void end_while() override { close("}"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s; for (auto& i : items) s += (s.empty() ? "" : " ") + i; open("for " + v + " in [" + s + "] {"); }
    void end_for() override { close("}"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        std::string s; for (auto& p : ps) s += (s.empty() ? "" : ", ") + p;
        open("def " + name + " [" + s + "] {");
        for (auto& p : ps) L("mut " + p + " = $" + p);   // parameters are assignable in C++
    }
    void end_fn() override { close("}"); }
    void ret(const std::string& v) override { L(v.empty() ? "return" : "return " + v); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety) override {
        std::string s = name; for (auto& x : a) s += " " + x;
        if (!want) { L(s + " | ignore"); return ""; }
        return "(" + s + ")";
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override { return "(if (" + n + " in $env) { $env | get " + n + " } else { " + d + " })"; }
    void setenv(const std::string& n, const std::string& v) override { L("load-env ({} | insert " + n + " " + v + ")"); }
    std::string test_path(const std::string& p, char k) override {
        if (k == 'e') return "(" + p + " | path exists)";
        return "((" + p + " | path type) == '" + (k == 'd' ? "dir" : "file") + "')";
    }
    void mkdir(const std::string& p) override { L("mkdir " + p); }
    void remove(const std::string& p) override { L("if (" + p + " | path exists) { rm -r " + p + " }"); }
    void write(const std::string& p, const std::string& s, bool app) override { L(s + " | save " + (app ? "-a " : "-f ") + p); }
    std::string read(const std::string& p) override { return "(open --raw " + p + ")"; }
    std::string cwd() override { return "$env.PWD"; }
    std::string platform() override { return "$nu.os-info.name"; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        L("let _x = (" + std::string(host ? "^nu --no-config-file -c " : "^sh -c ") + cmd + " | complete)");
        L("$" + o + " = $_x.stdout");
        L("$" + c + " = $_x.exit_code");
    }
    std::string sh_quote(const std::string& v) override { return "(\"'\" + (" + v + " | str replace -a \"'\" \"'\\\\''\") + \"'\")"; }
};
} // namespace
void forge_shell_register_nushell(forge::script::shell_registry& r) {
    forge::script::shell_backend b; b.name = "nu"; b.aliases = {"nushell"}; b.exes = {"nu"}; b.family = "nu"; b.golden_tested = true;
    b.argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> { return {exe, "--no-config-file", "-c", sc}; };
    b.quote = rq;
    b.emitter = [] { return std::make_unique<nu_dialect>(); }; b.emit_ext = ".nu"; b.emit_tested = true;
    r.add(std::move(b));
}
